-- esquerda (0280) pra bater com o formato usado em products.code — depois de rodar, confira
-- uns 2-3 produtos ao acaso (ex.: código 0280 = Mipuxa Azul) pra confirmar que os campos novos
-- vieram preenchidos; se não bateu nenhum, me avise que ajusto o casamento de código.

